FUNCTION_BLOCK FB_S01
VAR_INPUT
    StartBtn : BOOL;
    LeftPartPresent : BOOL;
    RightPartPresent : BOOL;
    EStop_NC : BOOL;
END_VAR
VAR_OUTPUT
    ClampLeft : BOOL := FALSE;
    ClampRight : BOOL := FALSE;
    Busy : BOOL := FALSE;
    Status : WORD := 16#0000;
END_VAR
VAR
    StartBtnLast : BOOL := FALSE;
    StartRise : BOOL := FALSE;
    RequestLeft : BOOL := FALSE;
    RequestRight : BOOL := FALSE;
    InitialScans : USINT := 0;
END_VAR

(*
需求原文：
双工位气动夹具用于同时定位两个零件，但气源只有一路，
因此两个夹具不能同时动作。

1. StartBtn 为上升沿触发：若左工位有零件
   （LeftPartPresent = TRUE）而右夹具未在夹紧，
   则左夹具 ClampLeft 夹紧；右侧对称。
2. 夹紧动作只做一次保持，不随 StartBtn 电平反复动作；
   要松开必须由同一按钮在另一工位动作时自动让位
   （即后启动的工位会等待）。
3. 任一工位没有零件（对应 PartPresent = FALSE）时，
   该侧不允许夹紧。
4. EStop_NC = FALSE（急停）时两侧夹具立即松开，
   ClampLeft 与 ClampRight 同时为 FALSE，并清空忙标志。
5. 任一时刻 ClampLeft 与 ClampRight 不得同时为 TRUE。
6. Busy 表示当前已有工位在夹紧过程中；
   Status 输出 16#0000 正常、16#8101 两侧同时请求、
   16#8102 急停中。

扫描周期：20 ms。

待审语义冲突：
A. C10 的 G[0,1] 要求前两个扫描输出均关闭，
   与这两个扫描内启动上升沿立即夹紧的要求存在冲突。
   本实现优先保持 C10；启动边沿仍采样，不延迟或重放。
B. 自动让位、后启动等待没有规定释放条件、等待完成条件
   或所需扫描数，且与“对侧未夹紧才允许启动”存在歧义。
   本实现采用保守互锁：对侧已夹紧时不接受新的夹紧动作，
   不擅自增加等待时间、排队规则或自动交接过程。
   自动让位条款仍待审，不能据此声称完整功能正确。
C. 两侧同时请求时没有指定仲裁工位。
   本实现报告 16#8101，不新增夹紧，保留合法的已有夹紧。

安全导致的松开优先于保持要求。
无夹紧完成反馈或动作时间参数；
Busy 按当前任一夹紧输出为 TRUE 计算。
本源码未经过真实编译器或逐周期测试验证。
*)

(* 每次调用均采样边沿，包括急停及初始化期间。 *)
StartRise := StartBtn AND NOT StartBtnLast;
StartBtnLast := StartBtn;

RequestLeft := StartRise AND LeftPartPresent;
RequestRight := StartRise AND RightPartPresent;

IF NOT EStop_NC THEN
    (* 急停最高优先级，当扫描释放，不保留请求。 *)
    ClampLeft := FALSE;
    ClampRight := FALSE;
    Busy := FALSE;
    Status := 16#8102;

ELSIF InitialScans < 2 THEN
    (* C10：以第一次调用为扫描 0，扫描 0、1 均禁止夹紧。 *)
    ClampLeft := FALSE;
    ClampRight := FALSE;
    Busy := FALSE;
    Status := 16#0000;

    IF RequestLeft AND RequestRight THEN
        Status := 16#8101;
    END_IF;

ELSE
    Status := 16#0000;

    (* 零件丢失必须当扫描释放。 *)
    IF NOT LeftPartPresent THEN
        ClampLeft := FALSE;
    END_IF;

    IF NOT RightPartPresent THEN
        ClampRight := FALSE;
    END_IF;

    (* 防御性互锁：非法双输出状态不进行工位仲裁，全部释放。 *)
    IF ClampLeft AND ClampRight THEN
        ClampLeft := FALSE;
        ClampRight := FALSE;
    END_IF;

    IF RequestLeft AND RequestRight THEN
        Status := 16#8101;

    ELSIF RequestLeft THEN
        IF NOT ClampRight THEN
            ClampLeft := TRUE;
        END_IF;

    ELSIF RequestRight THEN
        IF NOT ClampLeft THEN
            ClampRight := TRUE;
        END_IF;
    END_IF;

    (* 无新请求时保持此前合法夹紧状态。 *)
    Busy := ClampLeft OR ClampRight;
END_IF;

(* 上电保护按调用次数计数，急停期间也属于扫描周期。 *)
IF InitialScans < 2 THEN
    InitialScans := InitialScans + 1;
END_IF;

END_FUNCTION_BLOCK
